<script setup lang="ts">
/**
 * Value selection from a numeric range (`design/components/slider.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/slider.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/slider'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { agentMember, mergeParts, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/slider.module.css'

export interface SliderProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  defaultValue?: number | [number, number]
  disabled?: boolean
  /**
   * Formats both the readout and `aria-valuetext`.
   */
  formatValue?: (value: number) => string
  invalid?: boolean
  max?: number
  min?: number
  /**
   * Two thumbs on one track. The pair is `[low, high]` and the thumbs cannot cross.
   */
  range?: boolean
  /**
   * Shows the current value at the row's end. Decorative, because the thumb announces it.
   */
  showValue?: boolean
  step?: number
  value?: number | [number, number]
}

defineOptions({ name: 'Slider', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<SliderProps>(), {
  ariaRequired: undefined,
  disabled: false,
  formatValue: String,
  invalid: false,
  max: 100,
  min: 0,
  range: false,
  showValue: false,
  step: 1,
})
const emit = defineEmits<{
  change: [value: number | [number, number]]
  commit: [value: number | [number, number]]
}>()
const uid = useId()
const root = useTemplateRef<HTMLElement>('root')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    value:
      props.value === undefined
        ? undefined
        : Array.isArray(props.value)
          ? [...props.value]
          : [props.value],
    defaultValue:
      (props.defaultValue === undefined
        ? undefined
        : Array.isArray(props.defaultValue)
          ? [...props.defaultValue]
          : [props.defaultValue]) ?? (props.range ? [props.min, props.min] : [props.min]),
    min: props.min,
    max: props.max,
    step: props.step,
    disabled: props.disabled,
    invalid: props.invalid,
    getAriaValueText: (details) => props.formatValue(details.value),
    onValueChange: (details) => {
      emit(
        'change',
        props.range
          ? [details.value[0] ?? props.min, details.value[1] ?? props.min]
          : (details.value[0] ?? props.min),
      )
    },
    onValueChangeEnd: (details) => {
      emit(
        'commit',
        props.range
          ? [details.value[0] ?? props.min, details.value[1] ?? props.min]
          : (details.value[0] ?? props.min),
      )
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const spoken = computed(() => api.value.value.map((value) => props.formatValue(value)))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Slider',
    element: () => root.value?.querySelector('[role="slider"]'),
    state: () => ({
      value: api.value.value[0] ?? props.min,
      high: props.range ? (api.value.value[1] ?? props.min) : null,
      disabled: props.disabled,
      invalid: props.invalid,
    }),
    actions: {
      set: { argument: 'number', run: (value) => api.value.setThumbValue(0, value) },
      'set-high': {
        argument: 'number',
        run: (value) =>
          (() => {
            if (!props.range) throw new Error('A single slider has one value, which set moves.')
            api.value.setThumbValue(1, value)
          })(),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.root"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    data-orientation="horizontal"
    data-member="slider"
  >
    <span v-if="showValue" :class="styles.readout" aria-hidden="true">
      {{ spoken.join('–') }}
    </span>
    <!-- control -->
    <div v-bind="mergeParts(api.getRootProps(), api.getControlProps())" :class="styles.control">
      <!-- track -->
      <div v-bind="api.getTrackProps()" :class="styles.track">
        <!-- range -->
        <div v-bind="api.getRangeProps()" :class="styles.range" />
      </div>
      <template v-for="(_thumb, index) in api.value" :key="index">
        <!-- thumb -->
        <div
          v-bind="api.getThumbProps({ index })"
          :class="styles.thumb"
          :aria-label="ariaLabel"
          :aria-labelledby="ariaLabelledby"
          :aria-describedby="ariaDescribedby"
          :aria-required="ariaRequired"
          :aria-invalid="invalid ? true : undefined"
          :data-state="
            Object(api.getThumbProps({ index }))['data-dragging'] === '' ? 'dragging' : undefined
          "
        />
      </template>
    </div>
  </div>
</template>
